javascript:
frappe.query_reports["Retail Stock Balance"] = {
    filters: [
        {
            fieldname: "view",
            label: "View",
            fieldtype: "Select",
            options: "Short View\nFull View",
            default: "Short View",
            reqd: 1
        }
    ],

    formatter: function(value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);

        if (!data) {
            return value;
        }

        const stock_item_name = data.stock_item_name || "";
        const metal = data.metal || "";

        const is_header =
            stock_item_name === "CURRENT RETAIL STOCK SUMMARY" ||
            stock_item_name === "RETAIL STOCK DETAILS";

        const is_summary =
            !data.retail_stock_item &&
            (metal === "GOLD" || metal === "SILVER");

        if (is_header || is_summary) {
            return "<strong>" + value + "</strong>";
        }

        return value;
    }
};
